// --- helpers (function declarations: hoisted) ------------------------------

function normalizeSlashes(p) {
  return String(p == null ? '' : p).replace(/\\/g, '/');
}

function basename(p) {
  const norm = normalizeSlashes(p);
  return norm.slice(norm.lastIndexOf('/') + 1);
}

// Realpath the nearest EXISTING ancestor of an absolute POSIX path, re-appending
// the un-created tail — so a symlinked ancestor is resolved even when the file
// itself does not exist yet (F-017 symlink discipline).
function realpathAnchored(absPosix) {
  let cur = absPosix;
  const tail = [];
  for (;;) {
    try {
      const real = normalizeSlashes(fs.realpathSync(cur));
      return [real, ...tail].join('/').replace(/\/+/g, '/');
    } catch (e) {
      if (e.code !== 'ENOENT') return absPosix;
      const slash = cur.lastIndexOf('/');
      if (slash <= 0) return absPosix;
      tail.unshift(cur.slice(slash + 1));
      cur = cur.slice(0, slash);
    }
  }
}

// Resolve `rawPath` (relative -> against projectRoot) to an absolute POSIX path
// WITHOUT touching the filesystem, rejecting any `..` segment before resolution.
function resolveTarget(rawPath, projectRoot) {
  const norm = normalizeSlashes(rawPath);
  if (!norm) return null;
  if (norm.split('/').includes('..')) return null;
  return path.posix.isAbsolute(norm)
    ? path.posix.normalize(norm)
    : path.posix.normalize(normalizeSlashes(projectRoot) + '/' + norm);
}

// True iff `rawPath` resolves (lexically OR through a symlinked ancestor) to one
// of the protected serialized files under <projectRoot>/artifacts/context/.
function isProtected(rawPath, projectRoot) {
  const abs = resolveTarget(rawPath, projectRoot);
  if (!abs) return false;
  const root = path.posix.normalize(normalizeSlashes(projectRoot));
  const contextRoot = root + '/artifacts/context';
  const protectedAbs = PROTECTED_BASENAMES.map((n) => contextRoot + '/' + n);
  if (protectedAbs.includes(abs)) return true;
  // Symlink alias: does the candidate's real path match a protected real path?
  const realCandidate = realpathAnchored(abs);
  for (const p of protectedAbs) {
    if (realpathAnchored(p) === realCandidate) return true;
  }
  return false;
}

// True (returns the offending basename) iff a Bash command names a protected
// serialized file as a write/redirect target. Reads (cat/grep/git diff) pass.
function bashTargetsProtected(command) {
  const cmd = String(command);
  for (const name of PROTECTED_BASENAMES) {
    // Match the basename as a path token (optionally with a dir prefix), not a
    // substring of a longer name (ledger.md but not ledger.md.bak).
    const nameRe = new RegExp('(?:^|[\\s"\'=/>])([^\\s"\'<>|;&]*/)?' + name.replace(/\./g, '\\.') + '(?![\\w.-])');
    if (!nameRe.test(cmd)) continue;
    // The file is named; deny only if a write-shape is present.
    if (hasWriteShapeFor(cmd, name)) return name;
  }
  return false;
}

// Write-shape detectors: redirection onto the file, a write/edit binary naming
// it, or an interpreter eval that references it.
function hasWriteShapeFor(cmd, name) {
  const nameEsc = name.replace(/\./g, '\\.');
  // Redirection target: > >> &> >| pointing at the file (with optional dir).
  const redir = new RegExp('(?:>>?|&>|>\\|)\\s*(?:"[^"]*"|\'[^\']*\'|[^\\s|;&]*)' + nameEsc, 'i');
  if (redir.test(cmd)) return true;
  // Write/edit binaries anywhere in the command (coarse but this is a backstop).
  if (/\b(tee|dd|cp|mv|install|rsync|ln|truncate|patch|ed|ex|vim?|awk)\b/.test(cmd)) return true;
  if (/\bsed\b[^\n]*\s-i\b/.test(cmd) || /\bsed\b\s+-i/.test(cmd)) return true;
  // Interpreter inline-eval that mentions the file (node -e, python -c, …).
  if (/\b(node|nodejs|python3?|python2|perl|ruby|php)\b[^\n]*\s-(e|c|r|E)\b/.test(cmd)) return true;
  // A here-doc / printf writing pattern feeding the file is covered by redir;
  // a bare `> file` with no command still matched by redir above.
  return false;
}

